// SnapshotsServiceClient is a client for the elephant.tables.v1.SnapshotsService service.
type SnapshotsServiceClient interface {
	// CreateSnapshot takes an export snapshot, for downloads, round trips
	// and agent hand-offs. Publish snapshots are taken by Publish, and
	// restore points by DatabasesService.Restore.
	//
	// Auth: doc_read on the owning document.
	CreateSnapshot(context.Context, *connect.Request[v1.CreateSnapshotRequest]) (*connect.Response[v1.CreateSnapshotResponse], error)
	// GetSnapshot returns a snapshot's metadata and catalog, read without
	// opening the file, and a short-lived download URL.
	//
	// Auth: doc_read on the owning document. Snapshots are for the service
	// and for editors, for history and diffing; distribution reads
	// publications.
	GetSnapshot(context.Context, *connect.Request[v1.GetSnapshotRequest]) (*connect.Response[v1.GetSnapshotResponse], error)
	// ListSnapshots lists a database's snapshots, newest first. Paginated.
	//
	// Auth: doc_read on the owning document.
	ListSnapshots(context.Context, *connect.Request[v1.ListSnapshotsRequest]) (*connect.Response[v1.ListSnapshotsResponse], error)
	// Publish renders a publication. It forces a sync and waits until the
	// durable head covers the current state, takes a publish snapshot, and
	// renders the spec's tables, columns and rows from the snapshot alone,
	// as deterministic JSON. With snapshot set it re-renders from an
	// existing publish snapshot instead, without touching the live tables.
	//
	// Idempotent: a snapshot is keyed by its cursor and a publication by
	// its snapshot and spec, so a retry returns the existing ones. The
	// caller then sets the document status with a link to the publication.
	//
	// Auth: doc_write on the owning document.
	Publish(context.Context, *connect.Request[v1.PublishRequest]) (*connect.Response[v1.PublishResponse], error)
	// GetPublication returns a publication's metadata, its spec, the
	// catalog of the published columns, and a short-lived URL to download
	// the rendered JSON from.
	//
	// Auth: doc_read on the owning document.
	GetPublication(context.Context, *connect.Request[v1.GetPublicationRequest]) (*connect.Response[v1.GetPublicationResponse], error)
}

